#!/usr/bin/env python3
"""Synthetic protocol fixtures generated by the Python standard library, no device data."""
import pathlib
import plistlib
import sys
p = pathlib.Path(sys.argv[1])
p.mkdir(parents=True, exist_ok=True)
fixtures = {
    'screenshot_reply': ['DLMessageProcessMessage', {'MessageType': 'ScreenShotReply', 'ScreenShotData': b'NOT A REAL PNG\x00\xff'}],
    'metadata': {'Width': 1170, 'Height': 2532, 'Label': 'test', 'Long': 'x' * 300, 'UID': plistlib.UID(300), 'List': [0, 255, 256, 65536], 'Unicode': '\u4f60\u597d', 'Negative': -1, 'True': True, 'False': False, 'Null': None},
}
for name, value in fixtures.items():
    blob = plistlib.dumps(value, fmt=plistlib.FMT_BINARY, sort_keys=False)
    (p / (name + '.bplist')).write_bytes(blob)
with (p / 'fixtures.h').open('w') as f:
    f.write('/* Synthetic test fixtures. No real device capture or pairing material. */\n')
    for name in fixtures:
        blob = (p / (name + '.bplist')).read_bytes()
        f.write(f'static const unsigned char {name}[] = {{' + ','.join(str(b) for b in blob) + '};\n')
